/* @autogenerated */
package net.civeira.phylax.feature.oauth.tokensecurity.infrastructure.driven;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.Instant;

import javax.sql.DataSource;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.oauth.tokensecurity.domain.gateway.TokenRevocationGateway;

/**
 * JDBC adapter for JWT revocation storage.
 *
 * Writes and queries the {@code _oauth_revoked_jti} table. Theft detection uses a bulk INSERT
 * SELECT from {@code _oauth_session_token}.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class TokenRevocationSqlAdapter implements TokenRevocationGateway {

  private final DataSource datasource;

  @Override
  public boolean consumeJti(String jti, String tenantId, String tokenType, Instant expiresAt) {
    // The primary key on jti makes the insert the single winner of concurrent consumptions.
    try (Connection conn = datasource.getConnection();
        PreparedStatement ps = conn.prepareStatement(
            "INSERT IGNORE INTO _oauth_revoked_jti (jti, tenant_id, token_type, expires_at)"
                + " VALUES (?, ?, ?, ?)")) {
      ps.setString(1, jti);
      ps.setString(2, tenantId);
      ps.setString(3, tokenType);
      ps.setTimestamp(4, new Timestamp(expiresAt.toEpochMilli()));
      return ps.executeUpdate() == 1;
    } catch (SQLException ex) {
      throw new IllegalStateException(ex);
    }
  }

  @Override
  public void revokeJti(String jti, String tenantId, String tokenType, Instant expiresAt) {
    try (Connection conn = datasource.getConnection();
        PreparedStatement ps = conn.prepareStatement(
            "INSERT IGNORE INTO _oauth_revoked_jti (jti, tenant_id, token_type, expires_at)"
                + " VALUES (?, ?, ?, ?)")) {
      ps.setString(1, jti);
      ps.setString(2, tenantId);
      ps.setString(3, tokenType);
      ps.setTimestamp(4, new Timestamp(expiresAt.toEpochMilli()));
      ps.executeUpdate();
    } catch (SQLException ex) {
      throw new IllegalStateException(ex);
    }
  }

  @Override
  public boolean isRevoked(String jti, String tenantId) {
    try (Connection conn = datasource.getConnection();
        PreparedStatement ps = conn.prepareStatement("SELECT 1 FROM _oauth_revoked_jti"
            + " WHERE jti = ? AND tenant_id = ? AND expires_at > NOW()")) {
      ps.setString(1, jti);
      ps.setString(2, tenantId);
      try (ResultSet rs = ps.executeQuery()) {
        return rs.next();
      }
    } catch (SQLException ex) {
      throw new IllegalStateException(ex);
    }
  }

  @Override
  public void cleanup() {
    try (Connection conn = datasource.getConnection();
        PreparedStatement ps =
            conn.prepareStatement("DELETE FROM _oauth_revoked_jti WHERE expires_at < NOW()")) {
      ps.executeUpdate();
    } catch (SQLException ex) {
      throw new IllegalStateException(ex);
    }
  }

  /**
   * Revokes all non-expired refresh tokens for a user/client pair.
   *
   * Finds matching rows in {@code _oauth_session_token} using {@code client_id} and the
   * {@code username} field extracted from the JSON {@code auth_data} column, then bulk-inserts them
   * into {@code _oauth_revoked_jti}.
   */
  @Override
  public void revokeAllForSession(String sessionId, String tenantId) {
    String sql = "INSERT IGNORE INTO _oauth_revoked_jti (jti, tenant_id, token_type, expires_at)"
        + " SELECT st.jti, ?, 'access', st.expires_at" + " FROM _oauth_session_token st"
        + " WHERE st.session = ? AND st.jti IS NOT NULL AND st.expires_at > NOW() AND st.revoked_at IS NULL"
        + " UNION ALL" + " SELECT st.refresh_jti, ?, 'refresh', st.expires_at"
        + " FROM _oauth_session_token st"
        + " WHERE st.session = ? AND st.refresh_jti IS NOT NULL AND st.expires_at > NOW() AND st.revoked_at IS NULL";
    try (Connection conn = datasource.getConnection();
        PreparedStatement ps = conn.prepareStatement(sql)) {
      ps.setString(1, tenantId);
      ps.setString(2, sessionId);
      ps.setString(3, tenantId);
      ps.setString(4, sessionId);
      ps.executeUpdate();
    } catch (SQLException ex) {
      throw new IllegalStateException(ex);
    }
  }

  /**
   * Tokens of the user's interactive sessions with the client in this tenant.
   *
   * <p>
   * {@code auth_data.tenant} holds the uid of the user's tenant, the one the route tenant name
   * resolves to at login; matching it keeps another tenant's user with the same name and client
   * untouched (inserting their JTIs here would also make their next rotation look like a replay).
   */
  private static final String USER_TOKENS =
      " FROM _oauth_session_token st" + " WHERE st.client_id = ? AND st.auth_data IS NOT NULL"
          + "   AND JSON_UNQUOTE(JSON_EXTRACT(st.auth_data, '$.username')) = ?"
          + "   AND JSON_UNQUOTE(JSON_EXTRACT(st.auth_data, '$.tenant'))"
          + "       = (SELECT t.uid FROM identity_tenant t WHERE t.name = ?)"
          + "   AND st.expires_at > NOW() AND st.revoked_at IS NULL";

  @Override
  public void revokeAllForUser(String username, String clientId, String tenantId) {
    String sql = "INSERT IGNORE INTO _oauth_revoked_jti (jti, tenant_id, token_type, expires_at)"
        + " SELECT st.jti, ?, 'access', st.expires_at" + USER_TOKENS + " UNION ALL"
        + " SELECT st.refresh_jti, ?, 'refresh', st.expires_at" + USER_TOKENS;
    try (Connection conn = datasource.getConnection();
        PreparedStatement ps = conn.prepareStatement(sql)) {
      int index = 1;
      for (int part = 0; part < 2; part++) {
        ps.setString(index++, tenantId);
        ps.setString(index++, clientId);
        ps.setString(index++, username);
        ps.setString(index++, tenantId);
      }
      ps.executeUpdate();
    } catch (SQLException ex) {
      throw new IllegalStateException(ex);
    }
  }
}
